ALL_ENTRIES = LIUYAO + LIUREN + MEIHUA + NAMING + HEHUN + FENGSHUI

db = sqlite3.connect(DB)
cur = db.cursor()

inserted = 0
for module, title, category, content, keywords, trust in ALL_ENTRIES:
    eid = f"{module}-r366-{inserted+1}"
    try:
        cur.execute("SELECT 1 FROM kb_formal WHERE entry_id=?", (eid,))
        if cur.fetchone():
            continue
        cur.execute("""INSERT INTO kb_formal (entry_id, module, title, content, category, keywords, trust_score, status, audit_status, hit_count)
                       VALUES(?,?,?,?,?,?,?, 'active','approved',0)""", (eid, module, title, content, category, keywords, trust))
        inserted += 1
    except Exception as e:
        print(f"  跳过 {eid}: {e}")

# 同步 FTS5
cur.execute("""SELECT entry_id, module, title, content, keywords, category FROM kb_formal
               WHERE content IS NOT NULL AND length(content) >= 20
               AND entry_id NOT IN (SELECT entry_id FROM kb_fts5)""")
missing = cur.fetchall()
for eid, mod, title, content, kw, cat in missing:
    cur.execute("INSERT INTO kb_fts5(entry_id, module, title, content, keywords, category) VALUES(?,?,?,?,?,?)",
                (eid, mod, title or '', content or '', kw or '', cat or ''))

db.commit()

# 统计
print(f"新增条目: {inserted}")
print(f"  六爻: +{len(LIUYAO)}")
print(f"  六壬: +{len(LIUREN)}")
print(f"  梅花: +{len(MEIHUA)}")
print(f"  起名: +{len(NAMING)}")
print(f"  合婚: +{len(HEHUN)}")
print(f"  风水: +{len(FENGSHUI)}")
print(f"FTS5 同步: {len(missing)}")

for mod in ['liuyao','liuren','meihua','naming','hehun','fengshui','bazi','ziwei','qimen']:
    cur.execute("SELECT COUNT(*) FROM kb_formal WHERE module = ?", (mod,))
    print(f"  {mod}: {cur.fetchone()[0]}")

cur.execute("SELECT COUNT(*) FROM kb_formal")
total = cur.fetchone()[0]
cur.execute("SELECT COUNT(*) FROM kb_formal WHERE content IS NULL OR content = '' OR length(content) < 20")
empty = cur.fetchone()[0]
cur.execute("SELECT COUNT(*) FROM kb_fts5")
fts = cur.fetchone()[0]
print(f"\n总计: {total} 条 | 空: {empty} | FTS5: {fts} ({fts*100/total:.1f}%)")

db.close()
